mapper.select:
SELECT mm.MEMBER_NO ,mm.ORG_NO ,om.ORG_CD ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,mm.MEMBER_ID_ENC ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_NM) , ei.ENC_KEY) AS MEMBER_NM ,mm.MEMBER_STS_CD ,mm.JOIN_DT ,mm.LEAVE_DT ,mm.LAST_CONTACT_DT ,mm.REG_USER_ID ,mm.REG_DT ,mm.LAST_MOD_USER_ID ,mm.LAST_MOD_DT FROM T_MEMBER_MST mm INNER JOIN T_ORG_MST om ON om.ORG_NO = mm.ORG_NO
AND om.ORG_CD = #{orgCd}
AND om.ORG_NO = #{orgNo}
INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CONVERT (ei.TARGET_VAL, INT) WHERE 1 = 1
AND mm.MEMBER_NO = #{memberNo}
AND mm.ORG_NO = #{orgNo}
AND mm.MEMBER_ID_ENC = TO_BASE64(AES_ENCRYPT(#{memberId}, ei.ENC_KEY))
AND mm.MEMBER_ID_ENC = #{memberIdEnc}
AND mm.MEMBER_NM = TO_BASE64(AES_ENCRYPT(#{memberNm}, ei.ENC_KEY))
AND mm.MEMBER_STS_CD = #{memberStsCd}

SELECT * FROM ( SELECT mm.MEMBER_NO ,mm.ORG_NO ,om.ORG_CD ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,mm.MEMBER_ID_ENC ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_NM) , ei.ENC_KEY) AS MEMBER_NM ,mm.MEMBER_STS_CD ,mm.JOIN_DT ,mm.LEAVE_DT ,mm.LAST_CONTACT_DT ,mm.REG_USER_ID ,mm.REG_DT ,mm.LAST_MOD_USER_ID ,mm.LAST_MOD_DT FROM T_MEMBER_MST mm INNER JOIN T_ORG_MST om ON om.ORG_NO = mm.ORG_NO
AND om.ORG_CD = #{orgCd}
AND om.ORG_NO = #{orgNo}
INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CONVERT (ei.TARGET_VAL, INT) WHERE 1 = 1
AND mm.ORG_NO = #{orgNo}
AND mm.MEMBER_ID_ENC = TO_BASE64(AES_ENCRYPT(#{memberId}, ei.ENC_KEY))
AND mm.MEMBER_ID_ENC = #{memberIdEnc}
AND mm.MEMBER_NM = TO_BASE64(AES_ENCRYPT(#{memberNm}, ei.ENC_KEY))
AND mm.MEMBER_STS_CD = #{memberStsCd}
UNION ALL SELECT mm.MEMBER_NO ,mm.ORG_NO ,om.ORG_CD ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,mm.MEMBER_ID_ENC ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_NM) , ei.ENC_KEY) AS MEMBER_NM ,mm.MEMBER_STS_CD ,mm.JOIN_DT ,mm.LEAVE_DT ,mm.LAST_CONTACT_DT ,mm.REG_USER_ID ,mm.REG_DT ,mm.LAST_MOD_USER_ID ,mm.LAST_MOD_DT FROM T_MEMBER_MST mm INNER JOIN T_ORG_MST om ON om.ORG_NO = mm.ORG_NO
AND om.ORG_CD = #{orgCd}
AND om.ORG_NO = #{orgNo}
INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CONVERT (ei.TARGET_VAL, INT) INNER JOIN T_MEMBER_PID mp ON mp.MEMBER_NO = mm.MEMBER_NO
AND mp.ORG_NO = #{orgNo}
AND mp.PID_ENC = TO_BASE64(AES_ENCRYPT(#{memberId}, ei.ENC_KEY))
AND mp.PID_ENC = #{memberIdEnc}
AND mp.PID_STS_CD = #{memberStsCd}
WHERE 1 = 1
AND mm.ORG_NO = #{orgNo}
AND mm.MEMBER_STS_CD = #{memberStsCd}
) a LIMIT 1

SELECT
COUNT(*)
FROM T_MEMBER_MST mm
    INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CAST(ei.TARGET_VAL AS UNSIGNED)
WHERE 1 = 1

    AND mm.MEMBER_NO = #{memberNo}


    AND mm.ORG_NO = #{orgNo}


    AND mm.MEMBER_ID_ENC = TO_BASE64(AES_ENCRYPT(#{memberId}, ei.ENC_KEY))


    AND mm.MEMBER_ID_ENC = #{memberIdEnc}


    AND mm.MEMBER_NM = TO_BASE64(AES_ENCRYPT(#{memberNm}, ei.ENC_KEY))


    AND mm.MEMBER_STS_CD = #{memberStsCd}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY MEMBER_NO) ROW_NUM ,mm.MEMBER_NO ,mm.ORG_NO ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_ID_ENC) , ei.ENC_KEY) AS MEMBER_ID ,mm.MEMBER_ID_ENC ,AES_DECRYPT(FROM_BASE64(mm.MEMBER_NM) , ei.ENC_KEY) AS MEMBER_NM ,mm.MEMBER_STS_CD ,mm.JOIN_DT ,mm.LEAVE_DT ,mm.LAST_CONTACT_DT ,mm.REG_USER_ID ,mm.REG_DT ,mm.LAST_MOD_USER_ID ,mm.LAST_MOD_DT FROM T_MEMBER_MST mm INNER JOIN T_ENC_INFO ei ON ei.TARGET_GB_CD = 'ORG' AND mm.ORG_NO = CAST(ei.TARGET_VAL AS UNSIGNED) WHERE 1 = 1
AND mm.MEMBER_NO = #{memberNo}
AND mm.ORG_NO = #{orgNo}
AND mm.MEMBER_ID_ENC = TO_BASE64(AES_ENCRYPT(#{memberId}, ei.ENC_KEY))
AND mm.MEMBER_ID_ENC = #{memberIdEnc}
AND mm.MEMBER_NM = TO_BASE64(AES_ENCRYPT(#{memberNm}, ei.ENC_KEY))
AND mm.MEMBER_STS_CD = #{memberStsCd}
ORDER BY MEMBER_NO ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
